{
  "findings": [
    {
      "check_id": "UNKNOWN",
      "title": "Hardcoded administrator password",
      "resource": "azurerm_mysql_server.changeme_simple_mysql_server",
      "severity": "HIGH",
      "explanation": "The database administrator password is embedded directly in Terraform source, exposing it through source control and code review systems. Supplying it through a sensitive input variable prevents the credential from being stored in this file."
    },
    {
      "check_id": "CKV_AZURE_96",
      "title": "Infrastructure encryption is not enabled",
      "resource": "azurerm_mysql_server.changeme_simple_mysql_server",
      "severity": "MEDIUM",
      "explanation": "The server does not enable infrastructure-level double encryption, leaving stored data protected only by the default storage encryption layer."
    },
    {
      "check_id": "CKV_AZURE_94",
      "title": "Geo-redundant backups are not enabled",
      "resource": "azurerm_mysql_server.changeme_simple_mysql_server",
      "severity": "MEDIUM",
      "explanation": "Geo-redundant backup is not configured, reducing the ability to recover the database following a regional outage."
    },
    {
      "check_id": "CKV_AZURE_53",
      "title": "Public network access is enabled",
      "resource": "azurerm_mysql_server.changeme_simple_mysql_server",
      "severity": "MEDIUM",
      "explanation": "Public network access is not explicitly disabled and therefore defaults to allowing a public endpoint, increasing the database's network exposure."
    },
    {
      "check_id": "CKV_AZURE_54",
      "title": "Minimum TLS version is not enforced",
      "resource": "azurerm_mysql_server.changeme_simple_mysql_server",
      "severity": "MEDIUM",
      "explanation": "SSL enforcement is enabled, but the minimum TLS version is unspecified, so obsolete TLS protocol versions may remain accepted."
    },
    {
      "check_id": "CKV_AZURE_127",
      "title": "Threat detection is not enabled",
      "resource": "azurerm_mysql_server.changeme_simple_mysql_server",
      "severity": "MEDIUM",
      "explanation": "The server has no enabled threat detection policy, reducing visibility into anomalous or potentially malicious database activity."
    },
    {
      "check_id": "CKV2_AZURE_44",
      "title": "Private endpoint is not configured",
      "resource": "azurerm_mysql_server.changeme_simple_mysql_server",
      "severity": "MEDIUM",
      "explanation": "No private endpoint connects the MySQL server to a private subnet, so the configuration does not provide private network connectivity after public access is disabled."
    },
    {
      "check_id": "CKV2_AZURE_16",
      "title": "Customer-managed encryption key is not configured",
      "resource": "azurerm_mysql_server.changeme_simple_mysql_server",
      "severity": "MEDIUM",
      "explanation": "The server has no customer-managed key association, preventing independent control over encryption-key lifecycle, rotation, and revocation."
    }
  ],
  "patched_code": "variable \"mysql_administrator_login_password\" {\n  type        = string\n  description = \"Administrator password for the MySQL server.\"\n  sensitive   = true\n}\n\nvariable \"mysql_customer_managed_key_id\" {\n  type        = string\n  description = \"Resource ID of the Key Vault key used to encrypt the MySQL server.\"\n}\n\nvariable \"mysql_private_endpoint_subnet_id\" {\n  type        = string\n  description = \"Resource ID of the subnet in which to create the MySQL private endpoint.\"\n}\n\nresource \"azurerm_mysql_server\" \"changeme_simple_mysql_server\" {\n  name                = \"changeme-simple-mysql-database-name\"\n  resource_group_name = azurerm_resource_group.changeme_simple_mysql_server_resource_group.name\n  location            = azurerm_resource_group.changeme_simple_mysql_server_resource_group.location\n  storage_mb           = \"5120\"\n  sku_name             = \"GP_Gen5_2\"\n  version              = \"8.0\"\n\n  administrator_login          = \"changemeadmin\"\n  administrator_login_password = var.mysql_administrator_login_password\n\n  infrastructure_encryption_enabled = true\n  geo_redundant_backup_enabled       = true\n  public_network_access_enabled      = false\n  ssl_enforcement_enabled            = true\n  ssl_minimal_tls_version_enforced   = \"TLS1_2\"\n\n  identity {\n    type = \"SystemAssigned\"\n  }\n\n  threat_detection_policy {\n    enabled        = true\n    retention_days = 30\n  }\n}\n\nresource \"azurerm_mysql_server_key\" \"changeme_simple_mysql_server\" {\n  server_id        = azurerm_mysql_server.changeme_simple_mysql_server.id\n  key_vault_key_id = var.mysql_customer_managed_key_id\n}\n\nresource \"azurerm_private_endpoint\" \"changeme_simple_mysql_server\" {\n  name                = \"changeme-simple-mysql-private-endpoint\"\n  location            = azurerm_resource_group.changeme_simple_mysql_server_resource_group.location\n  resource_group_name = azurerm_resource_group.changeme_simple_mysql_server_resource_group.name\n  subnet_id           = var.mysql_private_endpoint_subnet_id\n\n  private_service_connection {\n    name                           = \"changeme-simple-mysql-private-connection\"\n    private_connection_resource_id = azurerm_mysql_server.changeme_simple_mysql_server.id\n    subresource_names              = [\"mysqlServer\"]\n    is_manual_connection           = false\n  }\n}\n",
  "fix_summary": "Replaced the hardcoded administrator password with a sensitive variable and enabled infrastructure encryption, geo-redundant backups, TLS 1.2, threat detection, and private-only network access. Added a private endpoint and customer-managed key association, with their environment-specific resource IDs supplied through variables."
}
